from __future__ import annotations

import argparse
import re
import sys
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent.parent
SYMBOLS_DIR = REPO_ROOT / "third_party" / "pmdsky-debug" / "symbols"
DEFAULT_OUT = REPO_ROOT / "include" / "skyrecomp" / "pmdsky_addrs.hpp"

# Core symbols required for native hooks (widescreen, interpolation, online rescue)
TARGET_SYMBOLS = [
    # Boot / crt0
    "_start",
    "NitroMain",
    "MIi_UncompressBackward",
    "do_autoload",
    "ExplorersOfSkyMain",
    # 2D / 3D Rendering & Window Primitives (arm9)
